from rdkit import Chem
from rdkit.Chem import AllChem
import numpy as np

base_ca = {"@": "[C@H]1", "@@": "[C@@H]1"}
base_cb = {"@": "[C@]", "@@": "[C@@]"}

def make_smiles(ca, cb):
    return f"{base_ca[ca]}(c2ccccc2N23)C25{base_cb[cb]}(CC)(CCC3(=O))CCCN5C(=O)C1"

def same_face_score(mol, conf):
    # least squares plane through atoms 0(Ca),8(Cc),9(Cb),7(Nb),19(Nt)
    idx = [0,8,9,7,19]
    pts = np.array([conf.GetAtomPosition(i) for i in idx])
    c = pts.mean(axis=0)
    _,_,vh = np.linalg.svd(pts-c)
    n = vh[-1]
    def sd(i):
        p = np.array(conf.GetAtomPosition(i))
        return float(np.dot(p-c, n))
    # H on Ca (atom0)
    hCa = [a.GetIdx() for a in mol.GetAtomWithIdx(0).GetNeighbors() if a.GetSymbol()=='H'][0]
    return sd(hCa), sd(10)

results = {}
for ca in ["@","@@"]:
    for cb in ["@","@@"]:
        sm = make_smiles(ca,cb)
        m = Chem.MolFromSmiles(sm)
        m = Chem.AddHs(m)
        best = None
        for seed in range(40):
            m2 = Chem.Mol(m)
            ps = AllChem.ETKDGv3()
            ps.randomSeed = seed+1
            if AllChem.EmbedMolecule(m2, ps) != 0:
                continue
            try:
                e = AllChem.MMFFOptimizeMolecule(m2, maxIters=500)
                ff = AllChem.MMFFGetMoleculeForceField(m2, AllChem.MMFFGetMoleculeProperties(m2))
                en = ff.CalcEnergy()
            except Exception as ex:
                continue
            if best is None or en < best[0]:
                best = (en, Chem.Mol(m2))
        if best:
            en, mbest = best
            conf = mbest.GetConformer()
            s_h, s_et = same_face_score(mbest, conf)
            results[(ca,cb)] = (en, s_h, s_et, mbest)
            print(f"ca={ca} cb={cb}  MMFF_E={en:8.2f}  sd(H)={s_h:+.2f} sd(Et)={s_et:+.2f}  sameface={s_h*s_et>0}")
import pickle
with open('embed_results.pkl','wb') as f:
    pickle.dump({k:(v[0],v[1],v[2],Chem.MolToMolBlock(v[3])) for k,v in results.items()}, f)
